import unittest

from hourglass.rounding import round_spans
from hourglass.models import Span


class RoundingTests(unittest.TestCase):
    # ---
    def test_rounds_to_nearest_step(self):
        spans = [Span(9 * 60 + 2, 17 * 60 + 14)]
        self.assertEqual(
            round_spans(spans, 15), ["09:00-17:15 (8h 15m)"]
        )

    # ---
    def test_rounds_half_up(self):
        spans = [Span(75, 128)]
        self.assertEqual(
            round_spans(spans, 15), ["01:15-02:15 (1h 0m)"]
        )

    # ---
    def test_labels_every_span(self):
        spans = [Span(0, 60), Span(60, 90)]
        self.assertEqual(len(round_spans(spans, 30)), 2)

    # ---
    def test_bad_steps_raise(self):
        for step in (0, -5, 7, 45):
            with self.assertRaises(ValueError):
                round_spans([Span(0, 60)], step)
